mapper.select:
select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wdr.warehouse_id in

        #{id}



    and wdr.affirm_time between #{startTime} and #{endTime}

and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr
    join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
    join wms_inventory wi on wi.id = info.inventory_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wi.shelf_id in

        #{id}



    and wdr.affirm_time between #{startTime} and #{endTime}

and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id, sum(quantity) as quantity  from wms_delivery_receipt wdr
join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id
join wms_inventory wi on wi.id = info.inventory_id
where wdr.del_flag = 0 and info.del_flag = 0







    and wdr.affirm_time between #{startTime} and #{endTime}


    and info.material_id in

        #{id}


and wdr.`status` in(1,2,3,5)
group by info.material_id;

select info.material_id,info.quantity as quantity,wdr.affirm_time,wi.material_code from wms_delivery_receipt wdr join wms_delivery_receipt_info info on wdr.id = info.delivery_receipt_id join wms_inventory wi on wi.id = info.inventory_id where wdr.del_flag = 0 and info.del_flag = 0
and wdr.affirm_time between #{startTime} and #{endTime}
and wdr.`status` in(1,2,3,5)
